cs[10]=(Check){"check_objectivec_11",check_objectivec_11,CAT_LANG_SPECIFIC,81011,LANG_OBJECTIVEC};
cs[11]=(Check){"check_objectivec_12",check_objectivec_12,CAT_LANG_SPECIFIC,81012,LANG_OBJECTIVEC};
